node --input-type=module <<'NODE'
import fs from 'node:fs';
const night = JSON.parse(fs.readFileSync('night.json'));
const plan = JSON.parse(fs.readFileSync('shift-plan.json'));
const receipt = JSON.parse(fs.readFileSync('operations/revision-receipt.json'));
const release = JSON.parse(fs.readFileSync('release.json'));
const caps = receipt.limits;
function calc(eta) {
  const out = {};
  for (const bus of night.buses) {
    let ac = 0;
    for (let s = bus.fromSlot; s < bus.untilSlot; s++) ac += plan.acKw[s] * night.slotHours;
    const end = bus.startKwh + ac * eta;
    out[bus.id] = {acKwh: ac, end: +end.toFixed(6), req: bus.requiredKwh, margin: +(end-bus.requiredKwh).toFixed(6)};
  }
  return out;
}
console.log('caps', caps);
console.log('withinCaps', plan.acKw.every((k,i)=>k<=caps[i]));
console.log('at90', calc(0.90));
console.log('at85', calc(0.85));
console.log('release', release);
if (JSON.stringify(release.departureKwh) !== JSON.stringify([calc(0.90).A.end, calc(0.90).B.end])) throw new Error('departure mismatch');
if (JSON.stringify(release.marginKwh) !== JSON.stringify([calc(0.90).A.margin, calc(0.90).B.margin])) throw new Error('margin mismatch');
console.log('RELEASE_OK');
NODE
